<template><div class="app-container">
<el-button v-if="mode==='apply'" type="primary" @click="edit()">新增企业申请</el-button><el-button @click="load">刷新</el-button>
<el-table :data="rows" v-loading="loading"><el-table-column prop="company_name" label="企业名称"/><el-table-column prop="credit_code" label="信用代码"/><el-table-column label="状态"><template #default="{row}">{{states[row.status]||row.status}}</template></el-table-column><el-table-column label="操作" width="300"><template #default="{row}"><el-button link @click="view(row)">详情</el-button><el-button v-if="mode==='manage'||mode==='apply'&&['DRAFT','REJECTED'].includes(row.status)" link type="primary" @click="edit(row)">修改</el-button><el-button v-if="mode==='apply'&&['DRAFT','REJECTED'].includes(row.status)" link type="primary" @click="submit(row)">提交</el-button><el-button v-if="mode==='review'&&row.status==='PENDING'" link type="primary" @click="review(row)">审核</el-button></template></el-table-column></el-table>
<el-dialog v-model="visible" :title="mode==='manage'?'企业资料':'企业入驻申请'" width="600px"><el-form label-width="120px"><el-form-item v-for="(label,key) in fields" :key="key" :label="label"><el-input v-model="form[key]" :disabled="key==='creditCode'&&mode==='manage'" :maxlength="key==='introduction'?2000:key==='address'?255:100" :type="key==='introduction'?'textarea':'text'"/></el-form-item><el-form-item v-if="mode!=='manage'" label="营业执照"><input type="file" accept=".pdf,.png,.jpg,.jpeg" @change="upload"/><span>{{form.licenseId?'已上传':'支持PDF/PNG/JPEG，最大5MB'}}</span></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
<el-dialog v-model="detailsVisible" title="申请详情与审核意见" width="650px"><el-descriptions :column="1" border><el-descriptions-item v-for="(label,key) in displayFields" :key="key" :label="label">{{detail[key]}}</el-descriptions-item></el-descriptions><el-button v-if="detail.qualification_ref" @click="download">下载营业执照</el-button><el-table :data="detail.audits||[]"><el-table-column prop="round_no" label="轮次"/><el-table-column prop="to_status" label="审核结果"/><el-table-column prop="opinion" label="意见"/></el-table></el-dialog>
<el-dialog v-model="reviewVisible" title="平台入驻审核" width="500px"><el-radio-group v-model="decision.approve"><el-radio :value="true">通过</el-radio><el-radio :value="false">驳回</el-radio></el-radio-group><el-input v-model="decision.opinion" type="textarea" maxlength="500" placeholder="审核意见必填"/><template #footer><el-button :loading="saving" type="primary" @click="decide">确认审核</el-button></template></el-dialog>
</div></template>
<script setup>
import {ref,computed,watch} from 'vue'
import {useRoute} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import request from '@/utils/request'
const route=useRoute(),mode=computed(()=>route.path.endsWith('company-review')?'review':route.path.endsWith('company-profile')?'manage':'apply')
const rows=ref([]),loading=ref(false),saving=ref(false),visible=ref(false),detailsVisible=ref(false),reviewVisible=ref(false),form=ref({}),detail=ref({}),decision=ref({})
const states={DRAFT:'草稿',PENDING:'待审核',REJECTED:'已驳回',APPROVED:'已通过',ACTIVE:'正常',DISABLED:'停用'}
const fields={companyName:'企业名称',creditCode:'统一社会信用代码',contactName:'企业负责人',contactPhone:'联系电话',address:'企业地址',introduction:'企业简介'}
const displayFields={company_name:'企业名称',credit_code:'信用代码',contact_name:'负责人',contact_phone:'联系电话',address:'地址',introduction:'企业简介',status:'状态'}
async function load(){loading.value=true;try{const r=await request({url:mode.value==='manage'?'/onboarding/companies':'/onboarding/applications',params:{review:mode.value==='review'}});rows.value=mode.value==='manage'?r.data:r.data.rows}finally{loading.value=false}}
function edit(row){form.value=row?{id:row.id,version:row.version,companyName:row.company_name,creditCode:row.credit_code,contactName:row.contact_name,contactPhone:row.contact_phone,address:row.address,introduction:row.introduction,licenseId:Number(row.qualification_ref)||undefined}:{};visible.value=true}
async function save(){saving.value=true;try{await request({url:'/onboarding/'+(mode.value==='manage'?'companies':'applications')+(form.value.id?'/'+form.value.id:''),method:form.value.id?'put':'post',data:form.value});visible.value=false;ElMessage.success('保存成功');await load()}finally{saving.value=false}}
async function upload(e){const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024){ElMessage.warning('文件不能超过5MB');return}const data=new FormData();data.append('file',file);const r=await request({url:'/onboarding/licenses',method:'post',data,headers:{'Content-Type':'multipart/form-data'}});form.value.licenseId=r.data;ElMessage.success('上传成功')}
async function view(row){detail.value=mode.value==='manage'?row:(await request({url:'/onboarding/applications/'+row.id})).data;detailsVisible.value=true}
async function submit(row){await ElMessageBox.confirm('确认提交企业入驻申请？');await request({url:`/onboarding/applications/${row.id}/submit`,method:'post'});ElMessage.success('已提交');await load()}
function review(row){decision.value={id:row.id,approve:true,opinion:''};reviewVisible.value=true}
async function decide(){if(!decision.value.opinion?.trim()){ElMessage.warning('请填写审核意见');return}saving.value=true;try{await request({url:`/onboarding/applications/${decision.value.id}/review`,method:'post',data:decision.value});reviewVisible.value=false;ElMessage.success('审核已完成；通过后申请人需重新登录刷新权限');await load()}finally{saving.value=false}}
async function download(){const data=await request({url:'/onboarding/licenses/'+detail.value.qualification_ref,responseType:'blob'});const url=URL.createObjectURL(data);const a=document.createElement('a');a.href=url;a.download='营业执照';a.click();URL.revokeObjectURL(url)}
watch(mode,()=>{visible.value=false;detailsVisible.value=false;reviewVisible.value=false;load()},{immediate:true})
</script>
